// Durable, effectively-once outbox for outbound provider mutations. One row per logical intent (unique per merchant on idempotency_key). Each is run by its own openrails.provider_operation River job, queued in the transaction that records it (a manual card removal runs only on request); an ambiguous outcome is resolved by provider reads before any retry. Retention: finished intents that only instructed a provider (cancel, update, archive, vault, token, account updater) are deleted 25 months (761 days) after they last changed; an intent that moved or refused money, enrolled a membership or erased a card is permanent.
type BillingProviderIntent struct {
	ID         uuid.UUID
	MerchantID uuid.UUID
	// Rail the mutation targets (e.g. 'nmi', 'stripe').
	Rail string
	// Registry key selecting the per-type semantics (executor, verifier, relevance, backoff), for example nmi_delete_subscription or manual_rebill.
	IntentType     string
	SubscriptionID *uuid.UUID
	PaymentID      *uuid.UUID
	PriceID        *uuid.UUID
	Payload        []byte
	// Deterministic identity of the logical intent within the merchant. Re-enqueues conflict here: a pending intent is refreshed, a superseded/expired one revived (relevance returned), anything else untouched — effectively-once per logical intent.
	IdempotencyKey string
	Status         string
	Attempts       int32
	NextAttemptAt  time.Time
	// The running attempt's claim. An in_flight row whose lease elapsed lost its attempt and becomes unknown_needs_verify: a provider read settles it before any retry.
	LeaseExpiresAt *time.Time
	// Who wanted this mutation: user/admin-origin intents execute under mode=limited (reactive completion), system-origin intents require mode=full. Nothing executes under mode=readonly.
	Origin       string
	OriginReason *string
	// The invoker that produced a user/admin-origin intent: the party that acted, the subject itself when it acted itself. NULL for system-origin. Keys the anti-credential-compromise rate ceiling (per-invoker + per-merchant rolling-hour count of destructive ops).
	Actor *string
	// Why the most recent attempt did not succeed (mode parked, kill switch, provider down, declined...). Recorded on the intent, never surfaced as an error.
	LastFailureReason *string
	// End of the relevance window: past this instant the intent expires with a finding instead of firing stale (NULL = relevance governed solely by the type's relevance check).
	ExpiresAt *time.Time
	// How the terminal status was established (e.g. {"verified_absent": true} for a delete confirmed by a provider read).
	ResultEvidence []byte
	CreatedAt      time.Time
	ExecutedAt     *time.Time
	UpdatedAt      time.Time
	// PSP the outbound intent was enqueued against. Required unless the intent is custodian-addressed (provider_intents_addressed_check).
	PspID *uuid.UUID
	// The destructive run whose pass enqueued this intent. The reverse of that run supersedes the ones still pending/failed_retryable and reports the rest — succeeded ones as irreversible provider-side divergence, in_flight/unknown_needs_verify ones as ambiguous. Attribution only: never cleared, never used to delete a row.
	DestructiveRunID    *uuid.UUID
	DestructiveRunClass *string
	// The custodian this outbound write is addressed to, for intents that target a custodian rather than a gateway account (the batch account updater). NULL for the ordinary PSP-addressed intent. Composite FK: an intent can only reference ITS OWN merchant's custodian.
	CustodianID *uuid.UUID
	// The subject whose authority produced a user/admin-origin intent: the staff member, application or customer. NULL for system-origin.
	Subject *string
	// How the subject proved itself for a user/admin-origin intent, as kind:id (session:…, api_key:…). NULL for system-origin.
	Credential *string
	// Original admitted command; recovery and necessary consequences reuse its authority and never spend another unit.
	DestructiveActionID *uuid.UUID
	// The attempt the destructive-volume breaker last admitted to the provider, set under its lock before the call. An in_flight intent counts against the breaker's budget only while this is its current attempt: a claim alone sends nothing.
	SentAttempt *int32
}

// Immutable accepted provider schedule versions: first due instant, cadence and the accepted bill a provider-run renewal must match. Retention: permanent, never pruned.
type BillingProviderSchedule struct {
	MerchantID        uuid.UUID
	SubscriptionID    uuid.UUID
	CustomerID        uuid.UUID
	PspID             uuid.UUID
	InitialOrderID    *uuid.UUID
	AcceptedVersion   int64
	SourceReference   string
	ProviderReference string
	FirstDueAt        time.Time
	CadenceHours      int32
	CadenceMonths     int32
	AcceptedBill      []byte
	CreatedAt         time.Time
}

// Bearer tokens a merchant's directory presents at /scim/v2, stored as their SHA-256. Revoking deletes the row.
type BillingProvisioningToken struct {
	MerchantID uuid.UUID
	ID         uuid.UUID
	Name       string
	// The merchant declaration's secrets.scim_token: at most one per merchant, replaced when the declaration changes it.
	Declared    bool
	TokenSha256 []byte
	LastUsedAt  *time.Time
	CreatedAt   time.Time
}

// Merchant PSP identities. A row is one merchant-owned account on one rail, the target of every payment, subscription and card that names it, with what OpenRails discovers about it; its configuration (settings, credentials, archived) is the PSP document in a file or Vault. The rail vocabulary lives here only; every table that stores rail beside psp_id references (merchant_id, id, rail).
type BillingPsp struct {
	ID         uuid.UUID
	MerchantID uuid.UUID
	// The merchant's name for the PSP (e.g. mobius): the key of its document. One current PSP holds a key.
	Key  string
	Rail string
	// The PSP's declared environment, its rail's own: nmi live, test or sandbox; stripe live or test; ccbill live or sandbox; solana mainnet, devnet or testnet.
	Environment string
	// Operator-declared account identity on the rail (Stripe acct_, NMI gateway id, CCBill account-subaccount, Solana signer address).
	AccountID string
	// When the provider last accepted the stored credentials; NULL when never checked.
	CredentialsValidatedAt *time.Time
	// The provider webhook endpoint OpenRails manages for this PSP.
	WebhookEndpointID *string
	CreatedAt         time.Time
	UpdatedAt         time.Time
	// HMAC-SHA256, under a key held in Vault, of the credential naming the gateway account (NMI security_key, Stripe secret_key). Cleared when the PSP archives.
	CredentialFingerprint *string
	// When this PSP was found to declare a gateway account another live PSP on its rail already declares. Its credentials are not read, so it stays disarmed, until it is archived or given its own.
	CredentialDuplicateAt *time.Time
	// When OpenRails found the PSP's key naming another account. A superseded PSP takes no new work and drains, as an archived one does.
	SupersededAt *time.Time
	// The PSP's money class: whether its environment moves real money (live, mainnet). A PSP's identity is (rail, live, account_id); a sandbox merchant's PSPs are non-live, a live merchant's live.
	Live bool
	// SHA-256 of the pinned Stripe API version, the handled event types and the webhook URL the PSP's managed endpoint was last settled at; NULL until one is.
	WebhookDigest *string
}

// A customer's customer object at one PSP. Two PSPs on one rail hold independent mappings.
type BillingPspCustomer struct {
	ID         uuid.UUID
	MerchantID uuid.UUID
	CustomerID uuid.UUID
	PspID      uuid.UUID
	// The PSP's own customer id (Stripe cus_). Unique only within the PSP that minted it.
	RemoteCustomerRef string
	CreatedAt         time.Time
	UpdatedAt         time.Time
}

// One read-only pull of a PSP's catalog, customers, subscriptions and transaction history, and the merchant's rules for linking them to customers. history_through is how far the transaction history has been read. Deleting the import deletes its records.
type BillingPspImport struct {
	MerchantID     uuid.UUID
	ID             uuid.UUID
	PspID          uuid.UUID
	Rail           string
	Status         string
	HistorySince   *time.Time
	HistoryThrough *time.Time
	PulledAt       *time.Time
	AppliedAt      *time.Time
	Error          *string
	Rules          []byte
	CreatedAt      time.Time
	UpdatedAt      time.Time
	// Why a failed import stopped when pulling it again would stop the same way: psp_credentials_rejected (the provider refused the credentials), psp_not_readable (the PSP, its rail's import or a credential is not declared) or pull_roster_implausible (the NMI roster listed under a tenth of the PSP's live subscriptions).
	ErrorCode *string
	// The person who last asked to apply the import; its corrections are approved in their name.
	ApplyRequestedBy *string
}

// Each subscription of the PSP an import found before it read the roster, at its row version: the import proposes a state change only for a row still at that version. Deleted with its import.
